namespace Bingo.Domain.Access;

public sealed class AccountDiscordIdentityTransition { private AccountDiscordIdentityTransition() { } public AccountDiscordIdentityTransition(Guid id, Guid accountId, string action, string? previousDiscordUserId, string? nextDiscordUserId, DateTimeOffset occurredAt) { Id = id; AccountId = accountId; Action = action; PreviousDiscordUserId = previousDiscordUserId; NextDiscordUserId = nextDiscordUserId; OccurredAt = occurredAt.ToUniversalTime(); } public Guid Id { get; private set; } public Guid AccountId { get; private set; } public string Action { get; private set; } = string.Empty; public string? PreviousDiscordUserId { get; private set; } public string? NextDiscordUserId { get; private set; } public DateTimeOffset OccurredAt { get; private set; } }
